public class Main {
    // O(log n) time: halve the range until it is empty
    static int binarySteps(int n) {
        int lo = 0, hi = n - 1, steps = 0;
        while (lo <= hi) {
            steps++;
            int mid = lo + (hi - lo) / 2;
            lo = mid + 1; // pretend the target is larger than everything
        }
        return steps;
    }

    public static void main(String[] args) {
        int[] sizes = {16, 1024, 1000000};
        for (int n : sizes) {
            long linear = n;                      // O(n): one loop
            long pairs = (long) n * (n - 1) / 2;  // O(n^2): every pair
            System.out.println("n=" + n + " binary=" + binarySteps(n)
                    + " linear=" + linear + " pairs=" + pairs);
        }
        // Space is O(1) here: only a few counters, whatever n is.
    }
}

