import java.util.*;

public class Main {
    // Sliding window: only correct when all numbers are >= 0
    static boolean window(int[] a, int k) {
        int left = 0, sum = 0;
        for (int right = 0; right < a.length; right++) {
            sum += a[right];
            while (sum > k && left <= right) sum -= a[left++]; // shrink when too big
            if (sum == k && left <= right) return true;
        }
        return false;
    }

    // Prefix sums in a set: correct for any numbers. O(n) time, O(n) space
    static boolean prefix(int[] a, int k) {
        Set<Integer> seen = new HashSet<>();
        seen.add(0); // empty prefix
        int sum = 0;
        for (int x : a) {
            sum += x;
            if (seen.contains(sum - k)) return true; // earlier prefix cuts off exactly k
            seen.add(sum);
        }
        return false;
    }

    public static void main(String[] args) {
        int[] a = {3, -2, 5};
        int k = 1; // the subarray [3, -2] adds up to 1
        System.out.println("array = " + Arrays.toString(a) + ", k = " + k);
        System.out.println("sliding window finds it: " + (window(a, k) ? "yes" : "no"));
        System.out.println("prefix sums find it: " + (prefix(a, k) ? "yes" : "no"));
    }
}

