    unordered_set<int> seen = {0}; // empty prefix
    int sum = 0;
    for (int x : a) {
        sum += x;
        if (seen.count(sum - k)) return true; // earlier prefix cuts off exactly k
        seen.insert(sum);
    }
    return false;
}

