class Program
{
    // Sliding window: only correct when all numbers are >= 0
    static bool Window(int[] a, int k)
    {
        int left = 0, sum = 0;
        for (int right = 0; right < a.Length; right++)
        {
            sum += a[right];
            while (sum > k && left <= right) sum -= a[left++]; // shrink when too big
            if (sum == k && left <= right) return true;
        }
        return false;
    }

    // Prefix sums in a set: correct for any numbers. O(n) time, O(n) space
    static bool Prefix(int[] a, int k)
    {
        var seen = new HashSet<int> { 0 }; // empty prefix
        int sum = 0;
        foreach (int x in a)
        {
            sum += x;
            if (seen.Contains(sum - k)) return true; // earlier prefix cuts off exactly k
            seen.Add(sum);
        }
        return false;
    }

    static void Main()
    {
        int[] a = { 3, -2, 5 };
        int k = 1; // the subarray [3, -2] adds up to 1
        Console.WriteLine("array = [" + string.Join(", ", a) + "], k = " + k);
        Console.WriteLine("sliding window finds it: " + (Window(a, k) ? "yes" : "no"));
        Console.WriteLine("prefix sums find it: " + (Prefix(a, k) ? "yes" : "no"));
