public class Main {
    // O(n) time, O(n) space for the char array (strings cannot be changed)
    static String reverse(String s) {
        char[] a = s.toCharArray();
        int i = 0, j = a.length - 1;
        while (i < j) {          // stop when the indexes meet
            char t = a[i];       // swap the two ends
            a[i] = a[j];
            a[j] = t;
            i++;
            j--;
        }
        return new String(a);
    }

    public static void main(String[] args) {
        String[] tests = {"interview", "ab", "x", ""};
        for (String s : tests)
            System.out.println("\"" + s + "\" -> \"" + reverse(s) + "\"");
    }
}

