public class Main {
    // O(n) time, O(1) extra space: no cleaned copy of the string is made
    static boolean isPalindrome(String s) {
        int i = 0, j = s.length() - 1;
        while (i < j) {
            if (!Character.isLetterOrDigit(s.charAt(i))) i++;        // skip on the left
            else if (!Character.isLetterOrDigit(s.charAt(j))) j--;   // skip on the right
            else {
                if (Character.toLowerCase(s.charAt(i)) != Character.toLowerCase(s.charAt(j)))
                    return false;                                    // first mismatch ends it
                i++;
                j--;
            }
        }
        return true; // empty text and one letter are palindromes
    }

    public static void main(String[] args) {
        String[] tests = {"A man, a plan, a canal: Panama", "race a car", "No lemon, no melon", ""};
        for (String s : tests)
            System.out.println("\"" + s + "\" -> " + (isPalindrome(s) ? "yes" : "no"));
    }
}

