import java.util.*;

public class Main {
    // O(n) time, O(k) space, where k is the number of different characters
    static String firstUnique(String s) {
        Map<Character, Integer> count = new HashMap<>();
        for (char c : s.toCharArray())               // pass 1: count every character
            count.put(c, count.getOrDefault(c, 0) + 1);
        for (char c : s.toCharArray())               // pass 2: the string keeps the order
            if (count.get(c) == 1) return String.valueOf(c);
        return "none";
    }

    public static void main(String[] args) {
        String[] tests = {"swiss", "level", "aabb", "z"};
        for (String s : tests)
            System.out.println(s + " -> " + firstUnique(s));
    }
}

