using System;
using System.Collections.Generic;

class Program
{
    // O(n) time, O(k) space, where k is the number of different characters
    static string FirstUnique(string s)
    {
        var count = new Dictionary<char, int>();
        foreach (char c in s)            // pass 1: count every character
        {
            int n;
            count.TryGetValue(c, out n); // n stays 0 when the key is new
            count[c] = n + 1;
        }
        foreach (char c in s)            // pass 2: the string keeps the order
            if (count[c] == 1) return c.ToString();
        return "none";
    }

    static void Main()
    {
        foreach (string s in new[] { "swiss", "level", "aabb", "z" })
            Console.WriteLine(s + " -> " + FirstUnique(s));
    }
}

