public class Main {
    // O(n) time, O(1) space: the array always has 26 cells (lowercase a to z)
    static boolean isAnagram(String a, String b) {
        if (a.length() != b.length()) return false; // different length: never anagrams
        int[] count = new int[26];
        for (int i = 0; i < a.length(); i++) {
            count[a.charAt(i) - 'a']++;             // up for the first string
            count[b.charAt(i) - 'a']--;             // down for the second
        }
        for (int c : count)
            if (c != 0) return false;               // a letter is left over
        return true;
    }

    public static void main(String[] args) {
        String[][] tests = {{"listen", "silent"}, {"apple", "papel"}, {"rat", "car"}, {"aab", "abb"}};
        for (String[] t : tests)
            System.out.println(t[0] + " / " + t[1] + " -> " + (isAnagram(t[0], t[1]) ? "anagrams" : "not anagrams"));
    }
}

