import java.util.*;

public class Main {
    public static void main(String[] args) {
        String s = "  the quick   brown fox ";
        // trim first, then split on one or more spaces: no empty words. O(n) time and space
        String[] words = s.trim().split("\\s+");
        System.out.println("input: \"" + s + "\"");
        System.out.println("word count: " + words.length);

        List<String> reversed = new ArrayList<>(Arrays.asList(words));
        Collections.reverse(reversed);               // reverse the list of words, not the letters
        System.out.println("reversed: " + String.join(" ", reversed));

        StringBuilder sb = new StringBuilder();
        for (String w : words) {
            if (sb.length() > 0) sb.append(' ');
            sb.append(Character.toUpperCase(w.charAt(0))).append(w.substring(1)); // first letter up
        }
        System.out.println("capitalised: " + sb);
    }
}

