public class Main {
    public static void main(String[] args) {
        // 1) Build text with a StringBuilder: one buffer that grows. O(n) time
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 10; i++) {
            if (i > 0) sb.append(',');
            sb.append(i);
        }
        System.out.println("builder result: " + sb);

        // 2) Count the copying that s = s + "x" does: every round copies the whole string
        int n = 1000;
        long concatCopies = 0, builderCopies = 0;
        int length = 0;
        for (int i = 0; i < n; i++) {
            length++;
            concatCopies += length;  // new string: all old characters + 1 are copied
            builderCopies += 1;      // builder: only the new character is written
        }
        System.out.println("appends: " + n);
        System.out.println("characters copied by concat: " + concatCopies);   // about n*n/2
        System.out.println("characters copied by builder: " + builderCopies); // n
    }
}

