import java.util.*;

public class Main {
    public static void main(String[] args) {
        String[] words = {"eat", "tea", "tan", "ate", "nat", "bat"};
        // LinkedHashMap keeps the keys in the order they were first seen
        Map<String, List<String>> groups = new LinkedHashMap<>();
        for (String w : words) {
            char[] letters = w.toCharArray();
            Arrays.sort(letters);                    // "tea" and "eat" both become "aet"
            String key = new String(letters);
            groups.computeIfAbsent(key, k -> new ArrayList<>()).add(w);
        }
        System.out.println("words: " + String.join(" ", words));
        for (Map.Entry<String, List<String>> e : groups.entrySet())
            System.out.println(e.getKey() + ": " + String.join(" ", e.getValue()));
        // Time O(n * k log k) for n words of length k, space O(n * k)
    }
}

