    // O(total characters) time, O(1) extra space apart from the result
    static String lcp(String[] strs) {
        if (strs.length == 0) return "";
        String prefix = strs[0];                       // first word is the first guess
        for (int i = 1; i < strs.length; i++) {
            while (!strs[i].startsWith(prefix))        // too long for this word
                prefix = prefix.substring(0, prefix.length() - 1); // drop the last letter
            if (prefix.isEmpty()) return "";           // nothing in common: stop early
        }
        return prefix;
    }

    public static void main(String[] args) {
        String[][] tests = {{"flower", "flow", "flight"}, {"dog", "car"}, {"same"}, {"interview", "internet", "into"}};
        for (String[] t : tests)
            System.out.println(String.join(", ", t) + " -> \"" + lcp(t) + "\"");
    }
}

