public class Main {
    // O(n) time, O(n) space for the result
    static String compress(String s) {
        if (s.isEmpty()) return "";
        StringBuilder sb = new StringBuilder();
        int count = 1;
        for (int i = 1; i <= s.length(); i++) {
            // i == length is the extra step that writes the last run
            if (i < s.length() && s.charAt(i) == s.charAt(i - 1)) {
                count++;                                 // same letter: the run grows
            } else {
                sb.append(s.charAt(i - 1)).append(count); // run ended: write letter + count
                count = 1;
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        String[] tests = {"aaabbc", "abc", "zzzzzzzzzzzz", "a", ""};
        for (String s : tests)
            System.out.println("\"" + s + "\" -> \"" + compress(s) + "\"");
    }
}

