import java.util.*;

public class Main {
    // O(n) time, O(n) space for the stack
    static boolean isValid(String s) {
        Deque<Character> open = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            if (c == '(' || c == '[' || c == '{') {
                open.push(c);                          // remember the opener
            } else {
                if (open.isEmpty()) return false;      // a closer with nothing open
                char top = open.pop();
                if ((c == ')' && top != '(') || (c == ']' && top != '[') || (c == '}' && top != '{'))
                    return false;                      // wrong kind of bracket
            }
        }
        return open.isEmpty();                         // nothing may stay open
    }

    public static void main(String[] args) {
        String[] tests = {"([]{})", "(]", "((", "())", ""};
        for (String s : tests)
            System.out.println("\"" + s + "\" -> " + (isValid(s) ? "valid" : "not valid"));
    }
}

