import java.util.*;

public class Main {
    // O(n) time, O(k) space for k different characters
    static int longest(String s) {
        Map<Character, Integer> last = new HashMap<>(); // last index of each character
        int start = 0, best = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            // only jump when the earlier copy is inside the window (>= start)
            if (last.containsKey(c) && last.get(c) >= start)
                start = last.get(c) + 1;
            last.put(c, i);
            best = Math.max(best, i - start + 1);       // window is start..i
        }
        return best;
    }

    public static void main(String[] args) {
        String[] tests = {"abcabcbb", "bbbbb", "pwwkew", "abba", ""};
        for (String s : tests)
            System.out.println("\"" + s + "\" -> " + longest(s));
    }
}

