        var last = new Dictionary<char, int>();   // last index of each character
        int start = 0, best = 0;
        for (int i = 0; i < s.Length; i++)
        {
            char c = s[i];
            int seenAt;
            // only jump when the earlier copy is inside the window (>= start)
            if (last.TryGetValue(c, out seenAt) && seenAt >= start) start = seenAt + 1;
            last[c] = i;
            best = Math.Max(best, i - start + 1);   // window is start..i
        }
        return best;
    }

    static void Main()
    {
        foreach (string s in new[] { "abcabcbb", "bbbbb", "pwwkew", "abba", "" })
            Console.WriteLine("\"" + s + "\" -> " + Longest(s));
    }
}

