public class Main {
    // Grow outwards from l and r while both sides match; return the length found
    static int expand(String s, int l, int r) {
        while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) {
            l--;
            r++;
        }
        return r - l - 1;
    }

    // O(n^2) time (2n - 1 centres, each up to n steps), O(1) extra space
    static String longestPalindrome(String s) {
        int start = 0, best = 0;
        for (int i = 0; i < s.length(); i++) {
            int len = Math.max(expand(s, i, i),       // odd length: centre is a letter
                               expand(s, i, i + 1));  // even length: centre is a gap
            if (len > best) {
                best = len;
                start = i - (len - 1) / 2;            // left end of this palindrome
            }
        }
        return s.substring(start, start + best);
    }

    public static void main(String[] args) {
        String[] tests = {"babad", "cbbd", "xracecary", "a", ""};
        for (String s : tests)
            System.out.println("\"" + s + "\" -> \"" + longestPalindrome(s) + "\"");
    }
}

