public class Main {
    public static void main(String[] args) {
        String s = "a😀b"; // a, the emoji U+1F600 (2 UTF-16 units), b
        System.out.println("UTF-16 units: " + s.length());
        System.out.println("code points: " + s.codePointCount(0, s.length()));

        // Wrong: reverse unit by unit. The two halves of the emoji swap places.
        StringBuilder units = new StringBuilder();
        for (int i = s.length() - 1; i >= 0; i--)
            units.append(String.format("%04X ", (int) s.charAt(i)));
        System.out.println("reversed by unit: " + units.toString().trim());

        // Right: reverse whole code points. O(n) time, O(n) space
        int[] cps = s.codePoints().toArray();
        StringBuilder points = new StringBuilder();
        for (int i = cps.length - 1; i >= 0; i--)
            points.append(String.format("U+%04X ", cps[i]));
        System.out.println("reversed by code point: " + points.toString().trim());
        // DE00 before D83D is not valid text; U+1F600 stays in one piece.
    }
}

