#include <bits/stdc++.h>
using namespace std;

int main() {
    u16string s = u"a\U0001F600b"; // a, the emoji U+1F600 (2 UTF-16 units), b
    // Join a surrogate pair (high D800..DBFF + low DC00..DFFF) into one code point
    vector<unsigned> cps;
    for (size_t i = 0; i < s.size(); i++) {
        unsigned u = s[i];
        if (u >= 0xD800 && u <= 0xDBFF && i + 1 < s.size())
            u = 0x10000 + ((u - 0xD800) << 10) + (s[++i] - 0xDC00);
        cps.push_back(u);
    }
    printf("UTF-16 units: %d\n", (int)s.size());
    printf("code points: %d\n", (int)cps.size());

    // Wrong: reverse unit by unit. The two halves of the emoji swap places.
    printf("reversed by unit:");
    for (int i = (int)s.size() - 1; i >= 0; i--) printf(" %04X", (unsigned)s[i]);
    printf("\n");

    // Right: reverse whole code points. O(n) time, O(n) space
    printf("reversed by code point:");
    for (int i = (int)cps.size() - 1; i >= 0; i--) printf(" U+%04X", cps[i]);
    printf("\n");
    return 0;
}

