class Program
{
    static void Main()
    {
        string s = "a😀b"; // a, the emoji U+1F600 (2 UTF-16 units), b
        // Join a surrogate pair into one code point
        var cps = new List<int>();
        for (int i = 0; i < s.Length; i++)
        {
            if (char.IsHighSurrogate(s[i]) && i + 1 < s.Length) { cps.Add(char.ConvertToUtf32(s[i], s[i + 1])); i++; }
            else cps.Add(s[i]);
        }
        Console.WriteLine("UTF-16 units: " + s.Length);
        Console.WriteLine("code points: " + cps.Count);

        // Wrong: reverse unit by unit. The two halves of the emoji swap places.
        var units = new List<string>();
        for (int i = s.Length - 1; i >= 0; i--) units.Add(((int)s[i]).ToString("X4"));
        Console.WriteLine("reversed by unit: " + string.Join(" ", units));

        // Right: reverse whole code points. O(n) time, O(n) space
        var points = new List<string>();
        for (int i = cps.Count - 1; i >= 0; i--) points.Add("U+" + cps[i].ToString("X4"));
        Console.WriteLine("reversed by code point: " + string.Join(" ", points));
    }
}

