public class Main {
    // O(n + m) time, O(1) space (the count array has a fixed 128 cells)
    static String minWindow(String s, String t) {
        int[] need = new int[128];
        for (char c : t.toCharArray()) need[c]++;
        int missing = t.length();                 // characters still not covered
        int left = 0, bestStart = 0, bestLen = Integer.MAX_VALUE;
        for (int right = 0; right < s.length(); right++) {
            if (need[s.charAt(right)] > 0) missing--; // this character was needed
            need[s.charAt(right)]--;                  // may go negative: a spare copy
            while (missing == 0) {                    // window covers t: try to shrink
                if (right - left + 1 < bestLen) {
                    bestLen = right - left + 1;
                    bestStart = left;
                }
                need[s.charAt(left)]++;
                if (need[s.charAt(left)] > 0) missing++; // we just lost a needed character
                left++;
            }
        }
        return bestLen == Integer.MAX_VALUE ? "(none)" : s.substring(bestStart, bestStart + bestLen);
    }

    public static void main(String[] args) {
        System.out.println("ADOBECODEBANC, ABC -> " + minWindow("ADOBECODEBANC", "ABC"));
        System.out.println("a, aa -> " + minWindow("a", "aa"));
        System.out.println("xyyzyzyx, xyz -> " + minWindow("xyyzyzyx", "xyz"));
    }
}

