      const l = s.charCodeAt(left);
      need[l]++;
      if (need[l] > 0) missing++;       // we just lost a needed character
      left++;
    }
  }
  return bestLen === Infinity ? "(none)" : s.substring(bestStart, bestStart + bestLen);
}

