public class Main {
    // O(n) time, O(n) space for the map
    static int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> seen = new HashMap<>();      // value -> index
        for (int i = 0; i < nums.length; i++) {
            int partner = target - nums[i];                // the number we need
            if (seen.containsKey(partner))
                return new int[] {seen.get(partner), i};   // partner was seen earlier
            seen.put(nums[i], i);                          // store after the check
        }
        return new int[0];                                 // no pair
    }

    public static void main(String[] args) {
        int[] nums = {2, 7, 11, 15};
        System.out.println("nums = " + Arrays.toString(nums));
        System.out.println("target 9 -> " + Arrays.toString(twoSum(nums, 9)));
        System.out.println("target 26 -> " + Arrays.toString(twoSum(nums, 26)));
        System.out.println("target 100 -> " + Arrays.toString(twoSum(nums, 100)));
        System.out.println("[3, 3] target 6 -> " + Arrays.toString(twoSum(new int[] {3, 3}, 6)));
    }
}

