import java.util.*;

public class Main {
    // O(n) time, O(1) extra space
    static int removeDuplicates(int[] a) {
        if (a.length == 0) return 0;
        int write = 1;                         // a[0] is always kept
        for (int read = 1; read < a.length; read++) {
            if (a[read] != a[write - 1]) {     // new value: different from the last kept one
                a[write] = a[read];
                write++;
            }
        }
        return write;                          // number of unique values
    }

    public static void main(String[] args) {
        int[] a = {1, 1, 2, 2, 2, 3, 4, 4};
        System.out.println("before: " + Arrays.toString(a));
        int n = removeDuplicates(a);
        System.out.println("new length: " + n);
        System.out.println("first " + n + " items: " + Arrays.toString(Arrays.copyOf(a, n)));
    }
}

