import java.util.*;

public class Main {
    // O(n) time, O(1) space. long avoids overflow of n * (n + 1) for a large n
    static long bySum(int[] a) {
        long n = a.length;
        long expected = n * (n + 1) / 2;   // 0 + 1 + ... + n
        long actual = 0;
        for (int x : a) actual += x;
        return expected - actual;          // what is left is the missing number
    }

    // XOR version: no overflow possible. x ^ x = 0, so every pair cancels
    static int byXor(int[] a) {
        int result = a.length;             // start with n, the index that the loop never reaches
        for (int i = 0; i < a.length; i++) result ^= i ^ a[i];
        return result;
    }

    public static void main(String[] args) {
        int[][] tests = {{3, 0, 1}, {0, 1, 2, 3, 5, 6}, {1}, {0}};
        for (int[] a : tests)
            System.out.println(Arrays.toString(a) + " -> sum: " + bySum(a) + ", xor: " + byXor(a));
    }
}

