import java.util.*;

public class Main {
    // O(n + m) time, O(n + m) space for the result
    static int[] merge(int[] a, int[] b) {
        int[] r = new int[a.length + b.length];
        int i = 0, j = 0, k = 0;
        while (i < a.length && j < b.length)
            r[k++] = (a[i] <= b[j]) ? a[i++] : b[j++]; // copy the smaller front value (<= keeps it stable)
        while (i < a.length) r[k++] = a[i++];          // one side ran out: copy the rest of the other
        while (j < b.length) r[k++] = b[j++];
        return r;
    }

    public static void main(String[] args) {
        int[] a = {1, 4, 7, 10}, b = {2, 4, 6};
        System.out.println("a = " + Arrays.toString(a) + ", b = " + Arrays.toString(b));
        System.out.println("merged: " + Arrays.toString(merge(a, b)));
        System.out.println("with empty: " + Arrays.toString(merge(new int[0], b)));
    }
}

