public class Main {
    // O(log n) time, O(1) space. Returns the index, or -1 when absent
    static int binarySearch(int[] a, int target) {
        int lo = 0, hi = a.length - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;       // avoids int overflow of (lo + hi)
            if (a[mid] == target) return mid;
            if (a[mid] < target) lo = mid + 1;  // target is in the right half
            else hi = mid - 1;                  // target is in the left half
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] a = {2, 5, 8, 12, 16, 23, 38};
        System.out.println("array: 2 5 8 12 16 23 38");
        for (int t : new int[] {23, 2, 38, 7, 100})
            System.out.println("find " + t + " -> " + binarySearch(a, t));
    }
}

