    // O(n) time, O(1) space. Returns null when there is no second distinct value
    static Integer secondLargest(int[] a) {
        Integer first = null, second = null;
        for (int x : a) {
            if (first == null || x > first) {
                second = first;                  // old largest becomes second
                first = x;
            } else if (x != first && (second == null || x > second)) {
                second = x;                      // between second and first, and not a duplicate of first
            }
        }
        return second;
    }

    public static void main(String[] args) {
        int[][] tests = {{12, 35, 1, 10, 34, 1}, {5, 5, 5}, {7}, {-3, -1, -2}, {10, 9}};
        for (int[] a : tests)
            System.out.println(Arrays.toString(a) + " -> " + secondLargest(a));
    }
}

