import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] a = {-2, 1, -3, 4, -1, 2, 1, -5, 4};
        int cur = a[0], best = a[0];
        int curStart = 0, bestStart = 0, bestEnd = 0;
        for (int i = 1; i < a.length; i++) {
            if (cur < 0) {            // a negative run only hurts: start fresh here
                cur = a[i];
                curStart = i;
            } else {
                cur += a[i];          // extend the current run
            }
            if (cur > best) {         // remember the best run and where it is
                best = cur;
                bestStart = curStart;
                bestEnd = i;
            }
        }
        System.out.println("array: " + Arrays.toString(a));
        System.out.println("largest sum: " + best);
        System.out.println("from index " + bestStart + " to " + bestEnd
                + ": " + Arrays.toString(Arrays.copyOfRange(a, bestStart, bestEnd + 1)));
        // O(n) time, O(1) space. All-negative input returns the largest single item.
    }
}

