import java.util.*;

public class Main {
    static void reverse(int[] a, int i, int j) {
        while (i < j) { int t = a[i]; a[i++] = a[j]; a[j--] = t; }
    }

    // O(n) time, O(1) space
    static void rotate(int[] a, int k) {
        if (a.length == 0) return;
        k %= a.length;                 // k may be larger than the length
        reverse(a, 0, a.length - 1);   // whole array
        reverse(a, 0, k - 1);          // first k items
        reverse(a, k, a.length - 1);   // the rest
    }

    public static void main(String[] args) {
        int[] a = {1, 2, 3, 4, 5, 6, 7};
        System.out.println("before: " + Arrays.toString(a));
        rotate(a, 3);
        System.out.println("rotate right by 3: " + Arrays.toString(a));
        rotate(a, 7 + 1);              // 8 % 7 = 1
        System.out.println("then rotate by 8 (same as 1): " + Arrays.toString(a));
    }
}

