import java.util.*;

public class Main {
    // O(n log n) time for the sort, O(n) space for the result
    static List<int[]> merge(int[][] intervals) {
        int[][] sorted = intervals.clone();
        Arrays.sort(sorted, (x, y) -> Integer.compare(x[0], y[0]));  // by start
        List<int[]> result = new ArrayList<>();
        for (int[] cur : sorted) {
            if (result.isEmpty() || cur[0] > result.get(result.size() - 1)[1]) {
                result.add(new int[] {cur[0], cur[1]});              // gap: start a new interval
            } else {
                int[] last = result.get(result.size() - 1);
                last[1] = Math.max(last[1], cur[1]);                 // overlap: stretch the last one
            }
        }
        return result;
    }

    public static void main(String[] args) {
        int[][] in = {{8, 10}, {1, 3}, {2, 6}, {15, 18}, {6, 7}};
        StringBuilder sb = new StringBuilder();
        for (int[] x : in) sb.append("[" + x[0] + "," + x[1] + "]");
        System.out.println("input:  " + sb);
        sb = new StringBuilder();
        for (int[] x : merge(in)) sb.append("[" + x[0] + "," + x[1] + "]");
        System.out.println("merged: " + sb);
    }
}

