public class Main {
    // O(n) time, O(1) extra space besides the result
    static int[] productExceptSelf(int[] a) {
        int n = a.length;
        int[] r = new int[n];
        r[0] = 1;
        for (int i = 1; i < n; i++) r[i] = r[i - 1] * a[i - 1];  // r[i] = product of everything LEFT of i
        int right = 1;
        for (int i = n - 1; i >= 0; i--) {
            r[i] *= right;                                        // multiply by the product RIGHT of i
            right *= a[i];
        }
        return r;
    }

    public static void main(String[] args) {
        int[][] tests = {{1, 2, 3, 4}, {2, 3, 0, 4}, {0, 0, 5}, {-1, 2, -3}};
        for (int[] a : tests)
            System.out.println(Arrays.toString(a) + " -> " + Arrays.toString(productExceptSelf(a)));
    }
}

