public class Main {
    // O(n) time, O(1) space
    static int maxProfit(int[] prices) {
        int minPrice = Integer.MAX_VALUE, best = 0;
        for (int p : prices) {
            if (p < minPrice) minPrice = p;           // cheapest day so far
            else best = Math.max(best, p - minPrice); // sell today, bought at the cheapest
        }
        return best;                                  // 0 means "do not trade"
    }

    // Many trades allowed: add every rise. O(n) time
    static int maxProfitMany(int[] prices) {
        int total = 0;
        for (int i = 1; i < prices.length; i++)
            if (prices[i] > prices[i - 1]) total += prices[i] - prices[i - 1];
        return total;
    }

    public static void main(String[] args) {
        int[][] tests = {{7, 1, 5, 3, 6, 4}, {7, 6, 4, 3, 1}, {1, 2, 3, 4, 5}};
        for (int[] t : tests)
            System.out.println(java.util.Arrays.toString(t) + " -> once: " + maxProfit(t) + ", many: " + maxProfitMany(t));
    }
}

