public class Main {
    // O(n) time, O(1) space
    static int maxArea(int[] h) {
        int l = 0, r = h.length - 1, best = 0;
        while (l < r) {
            int width = r - l;
            int area = width * Math.min(h[l], h[r]);   // water is limited by the shorter line
            best = Math.max(best, area);
            if (h[l] < h[r]) l++; else r--;            // only moving the shorter line can help
        }
        return best;
    }

    public static void main(String[] args) {
        int[][] tests = {{1, 8, 6, 2, 5, 4, 8, 3, 7}, {1, 1}, {4, 3, 2, 1, 4}, {1, 2, 1}};
        for (int[] t : tests)
            System.out.println(java.util.Arrays.toString(t) + " -> " + maxArea(t));
    }
}

