public class Main {
    // O(n) time, O(1) space, one pass
    static void sortColors(int[] a) {
        int lo = 0, mid = 0, hi = a.length - 1;
        while (mid <= hi) {
            if (a[mid] == 0) {
                int t = a[lo]; a[lo] = a[mid]; a[mid] = t;  // 0 goes to the front zone
                lo++; mid++;
            } else if (a[mid] == 1) {
                mid++;                                      // 1 is already in the middle zone
            } else {
                int t = a[hi]; a[hi] = a[mid]; a[mid] = t;  // 2 goes to the back zone
                hi--;                                       // do not advance mid: new item unchecked
            }
        }
    }

    public static void main(String[] args) {
        int[][] tests = {{2, 0, 2, 1, 1, 0}, {2, 0, 1}, {1, 1, 1}, {2, 2, 0, 0}};
        for (int[] a : tests) {
            String before = Arrays.toString(a);
            sortColors(a);
            System.out.println(before + " -> " + Arrays.toString(a));
        }
    }
}

