public class Main {
    // O(n) time, O(1) space. Assumes a majority exists (we verify it below)
    static int majority(int[] a) {
        int candidate = 0, votes = 0;
        for (int x : a) {
            if (votes == 0) candidate = x;        // no candidate: pick this one
            votes += (x == candidate) ? 1 : -1;   // same value adds a vote, a different one cancels
        }
        return candidate;
    }

    static boolean verify(int[] a, int c) {       // needed when a majority is not guaranteed
        int count = 0;
        for (int x : a) if (x == c) count++;
        return count > a.length / 2;
    }

    public static void main(String[] args) {
        int[][] tests = {{2, 2, 1, 1, 1, 2, 2}, {3, 2, 3}, {1, 2, 3}, {5}};
        for (int[] a : tests) {
            int c = majority(a);
            System.out.println(java.util.Arrays.toString(a) + " -> candidate " + c
                    + (verify(a, c) ? " (majority)" : " (not a majority)"));
        }
    }
}

