public class Main {
    // O(n) time, O(n) space
    static int subarraySum(int[] a, int k) {
        Map<Integer, Integer> seen = new HashMap<>();
        seen.put(0, 1);                  // the empty prefix: a subarray that starts at index 0
        int sum = 0, count = 0;
        for (int x : a) {
            sum += x;                    // running (prefix) sum up to here
            count += seen.getOrDefault(sum - k, 0);  // each earlier prefix with sum - k gives one subarray
            seen.merge(sum, 1, Integer::sum);
        }
        return count;
    }

    public static void main(String[] args) {
        System.out.println("[1, 1, 1], k=2 -> " + subarraySum(new int[] {1, 1, 1}, 2));
        System.out.println("[1, 2, 3], k=3 -> " + subarraySum(new int[] {1, 2, 3}, 3));
        System.out.println("[3, -3, 3, -3], k=0 -> " + subarraySum(new int[] {3, -3, 3, -3}, 0));
        System.out.println("[1, -1, 0], k=0 -> " + subarraySum(new int[] {1, -1, 0}, 0));
    }
}

