// O(n) time, O(n) space
int subarraySum(const vector<int>& a, int k) {
    unordered_map<int, int> seen;
    seen[0] = 1;                    // the empty prefix: a subarray that starts at index 0
    int sum = 0, count = 0;
    for (int x : a) {
