using System;
using System.Collections.Generic;

class Program
{
    // O(n) time, O(n) space
    static int SubarraySum(int[] a, int k)
    {
        var seen = new Dictionary<int, int>();
        seen[0] = 1;                       // the empty prefix: a subarray that starts at index 0
        int sum = 0, count = 0;
        foreach (int x in a)
        {
            sum += x;                      // running (prefix) sum up to here
            int c;
            if (seen.TryGetValue(sum - k, out c)) count += c; // each earlier prefix with sum - k gives one subarray
            int old;
            seen.TryGetValue(sum, out old);
            seen[sum] = old + 1;
        }
        return count;
    }

