import java.util.*;

public class Main {
    // O(n^2) time, O(1) extra space besides the result and the sort
    static List<String> threeSum(int[] nums) {
        int[] a = nums.clone();
        Arrays.sort(a);
        List<String> result = new ArrayList<>();
        for (int i = 0; i < a.length - 2; i++) {
            if (i > 0 && a[i] == a[i - 1]) continue;         // skip a repeated first number
            int l = i + 1, r = a.length - 1;
            while (l < r) {
                int sum = a[i] + a[l] + a[r];
                if (sum < 0) l++;
                else if (sum > 0) r--;
                else {
                    result.add(a[i] + "," + a[l] + "," + a[r]);
                    l++; r--;
                    while (l < r && a[l] == a[l - 1]) l++;   // skip repeated values
                    while (l < r && a[r] == a[r + 1]) r--;
                }
            }
        }
        return result;
    }

    public static void main(String[] args) {
        int[] nums = {-1, 0, 1, 2, -1, -4};
        System.out.println("input: " + Arrays.toString(nums));
        System.out.println("triplets: " + threeSum(nums));
        System.out.println("[0, 0, 0, 0] -> " + threeSum(new int[] {0, 0, 0, 0}));
        System.out.println("[1, 2, 3] -> " + threeSum(new int[] {1, 2, 3}));
    }
}

