// O(log n) time, O(1) space. No duplicates in the array
int searchRotated(const vector<int>& a, int target) {
    int lo = 0, hi = (int)a.size() - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == target) return mid;
        if (a[lo] <= a[mid]) {                                   // left half is sorted
            if (a[lo] <= target && target < a[mid]) hi = mid - 1; // target is inside it
            else lo = mid + 1;
        } else {                                                 // right half is sorted
            if (a[mid] < target && target <= a[hi]) lo = mid + 1;
            else hi = mid - 1;
        }
    }
    return -1;
}

int main() {
    vector<int> a = {4, 5, 6, 7, 0, 1, 2};
    cout << "array: [4, 5, 6, 7, 0, 1, 2]\n";
    for (int t : {0, 4, 2, 5, 3})
        cout << "find " << t << " -> " << searchRotated(a, t) << "\n";
    return 0;
}

