import java.util.*;

public class Main {
    // O(n) time (each index enters and leaves the deque once), O(k) space
    static int[] maxSliding(int[] a, int k) {
        int[] res = new int[a.length - k + 1];
        Deque<Integer> dq = new ArrayDeque<>();             // indexes, values go from large to small
        for (int i = 0; i < a.length; i++) {
            if (!dq.isEmpty() && dq.peekFirst() <= i - k) dq.pollFirst();   // front left the window
            while (!dq.isEmpty() && a[dq.peekLast()] <= a[i]) dq.pollLast(); // smaller ones can never win
            dq.addLast(i);
            if (i >= k - 1) res[i - k + 1] = a[dq.peekFirst()];             // front is the maximum
        }
        return res;
    }

    public static void main(String[] args) {
        int[] a = {1, 3, -1, -3, 5, 3, 6, 7};
        System.out.println("array: " + Arrays.toString(a) + ", k = 3");
        System.out.println("window maximums: " + Arrays.toString(maxSliding(a, 3)));
        System.out.println("k = 1: " + Arrays.toString(maxSliding(new int[] {4, 2, 9}, 1)));
    }
}

