// A plain array with a head index works as a deque here
function maxSliding(a, k) {
  const res = [];
  const dq = [];            // indexes, values go from large to small
  let head = 0;
  for (let i = 0; i < a.length; i++) {
    if (head < dq.length && dq[head] <= i - k) head++;                  // front left the window
    while (dq.length > head && a[dq[dq.length - 1]] <= a[i]) dq.pop();  // smaller ones can never win
    dq.push(i);
    if (i >= k - 1) res.push(a[dq[head]]);                              // front is the maximum
  }
  return res;
}

