// O(n) time (each index enters and leaves the deque once), O(k) space
vector<int> maxSliding(const vector<int>& a, int k) {
    vector<int> res;
    deque<int> dq;                                       // indexes, values go from large to small
    for (int i = 0; i < (int)a.size(); i++) {
        if (!dq.empty() && dq.front() <= i - k) dq.pop_front();     // front left the window
        while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();  // smaller ones can never win
        dq.push_back(i);
        if (i >= k - 1) res.push_back(a[dq.front()]);               // front is the maximum
    }
    return res;
}

