public class Main {
    // O(n) time, O(1) space
    static int trap(int[] h) {
        int l = 0, r = h.length - 1, leftMax = 0, rightMax = 0, water = 0;
        while (l < r) {
            if (h[l] < h[r]) {                     // the left side is the limit
                if (h[l] >= leftMax) leftMax = h[l];
                else water += leftMax - h[l];      // water above this bar
                l++;
            } else {                               // the right side is the limit
                if (h[r] >= rightMax) rightMax = h[r];
                else water += rightMax - h[r];
                r--;
            }
        }
        return water;
    }

    public static void main(String[] args) {
        int[][] tests = {{0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1}, {4, 2, 0, 3, 2, 5}, {1, 2, 3}, {3, 0, 2, 0, 4}};
        for (int[] t : tests)
            System.out.println(java.util.Arrays.toString(t) + " -> " + trap(t));
    }
}

