public class Main {
    // O(n) time, O(1) space. Valid only when all numbers are >= 0
    static int longestAtMost(int[] a, int k) {
        int left = 0, sum = 0, best = 0;
        for (int right = 0; right < a.length; right++) {
            sum += a[right];                         // grow the window on the right
            while (sum > k && left <= right)         // too big: shrink from the left
                sum -= a[left++];
            best = Math.max(best, right - left + 1);
        }
        return best;
    }

    public static void main(String[] args) {
        int[] a = {2, 1, 3, 1, 1, 4};
        System.out.println("array: " + java.util.Arrays.toString(a));
        for (int k : new int[] {5, 3, 0, 12})
            System.out.println("K = " + k + " -> length " + longestAtMost(a, k));
    }
}

