import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[][] m = {{1, 2, 3}, {4, 5, 6}};           // Java arrays of arrays are "jagged" by nature
        int rows = m.length, cols = m[0].length;
        int[] rowSum = new int[rows], colSum = new int[cols];
        for (int r = 0; r < rows; r++)                // row loop outside, column loop inside
            for (int c = 0; c < cols; c++) {
                rowSum[r] += m[r][c];
                colSum[c] += m[r][c];
            }
        System.out.println("matrix: " + Arrays.deepToString(m));
        System.out.println("row sums: " + Arrays.toString(rowSum));
        System.out.println("column sums: " + Arrays.toString(colSum));
        int[][] jagged = {{1}, {2, 3}, {4, 5, 6}};     // each row has its own length
        System.out.println("jagged row lengths: " + jagged[0].length + " " + jagged[1].length + " " + jagged[2].length);
        // O(rows * cols) time, O(rows + cols) space
    }
}

