import java.util.*;

public class Main {
    static int[][] transpose(int[][] m) {
        int rows = m.length, cols = m[0].length;
        int[][] t = new int[cols][rows];              // the new matrix has swapped dimensions
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                t[c][r] = m[r][c];                    // row r, column c moves to row c, column r
        return t;
    }

    public static void main(String[] args) {
        int[][] m = {{1, 2, 3}, {4, 5, 6}};
        System.out.println("matrix: " + Arrays.deepToString(m));
        System.out.println("transpose: " + Arrays.deepToString(transpose(m)));

        int[][] sq = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
        int n = sq.length, main = 0, anti = 0;
        for (int i = 0; i < n; i++) {                 // O(n) for the diagonals
            main += sq[i][i];                         // top-left to bottom-right
            anti += sq[i][n - 1 - i];                 // top-right to bottom-left
        }
        System.out.println("square: " + Arrays.deepToString(sq));
        System.out.println("main diagonal = " + main + ", anti diagonal = " + anti);
    }
}

