    int rows = m.size(), cols = m[0].size();
    Mat t(cols, vector<int>(rows));          // the new matrix has swapped dimensions
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++)
            t[c][r] = m[r][c];               // row r, column c moves to row c, column r
