public class Main {
    // O(n^2) time, O(1) extra space
    static void rotate90(int[][] m) {
        int n = m.length;
        for (int i = 0; i < n; i++)                  // step 1: transpose (swap across the diagonal)
            for (int j = i + 1; j < n; j++) {
                int t = m[i][j]; m[i][j] = m[j][i]; m[j][i] = t;
            }
        for (int[] row : m)                          // step 2: reverse every row
            for (int a = 0, b = n - 1; a < b; a++, b--) {
                int t = row[a]; row[a] = row[b]; row[b] = t;
            }
    }

    public static void main(String[] args) {
        int[][] m = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
        System.out.println("before: " + Arrays.deepToString(m));
        rotate90(m);
        System.out.println("after:  " + Arrays.deepToString(m));
    }
}

