public class Main {
    // O(rows + cols) time, O(1) space
    static boolean search(int[][] m, int target) {
        int r = 0, c = m[0].length - 1;                // start at the top-right corner
        while (r < m.length && c >= 0) {
            if (m[r][c] == target) return true;
            if (m[r][c] > target) c--;                 // too big: everything below is bigger, go left
            else r++;                                  // too small: everything to the left is smaller, go down
        }
        return false;
    }

    public static void main(String[] args) {
        int[][] m = {{1, 4, 7, 11}, {2, 5, 8, 12}, {3, 6, 9, 16}, {10, 13, 14, 17}};
        System.out.println("matrix rows: 1 4 7 11 | 2 5 8 12 | 3 6 9 16 | 10 13 14 17");
        for (int t : new int[] {5, 16, 15, 1, 0})
            System.out.println("find " + t + " -> " + search(m, t));
    }
}

