import java.util.*;

public class Main {
    // O(rows * cols) time and space. Returns the number of steps, or -1 when there is no path
    static int shortestPath(String[] grid) {
        int rows = grid.length, cols = grid[0].length();
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) Arrays.fill(row, -1);               // -1 = not visited
        Deque<int[]> queue = new ArrayDeque<>();
        if (grid[0].charAt(0) == '#') return -1;
        dist[0][0] = 0;
        queue.add(new int[] {0, 0});
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();                              // cells come out in order of distance
            if (cur[0] == rows - 1 && cur[1] == cols - 1) return dist[cur[0]][cur[1]];
            for (int d = 0; d < 4; d++) {
                int nr = cur[0] + dr[d], nc = cur[1] + dc[d];
                if (nr < 0 || nc < 0 || nr >= rows || nc >= cols) continue;
                if (grid[nr].charAt(nc) == '#' || dist[nr][nc] != -1) continue;
                dist[nr][nc] = dist[cur[0]][cur[1]] + 1;
                queue.add(new int[] {nr, nc});
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        String[] open = {"..#.", ".##.", "....", "#..."};
        String[] blocked = {".#", "#."};
        System.out.println("grid: " + String.join(" ", open) + " -> " + shortestPath(open));
        System.out.println("grid: " + String.join(" ", blocked) + " -> " + shortestPath(blocked));
    }
}

