class Program
{
    // O(rows * cols) time and space. Returns the number of steps, or -1 when there is no path
    static int ShortestPath(string[] grid)
    {
        int rows = grid.Length, cols = grid[0].Length;
        if (grid[0][0] == '#') return -1;
        var dist = new int[rows, cols];
        for (int i = 0; i < rows; i++)
            for (int j = 0; j < cols; j++) dist[i, j] = -1;      // -1 = not visited
        var queue = new Queue<int[]>();
        dist[0, 0] = 0;
        queue.Enqueue(new[] { 0, 0 });
        int[] dr = { 1, -1, 0, 0 }, dc = { 0, 0, 1, -1 };
        while (queue.Count > 0)
        {
            int[] cur = queue.Dequeue();                         // cells come out in order of distance
            if (cur[0] == rows - 1 && cur[1] == cols - 1) return dist[cur[0], cur[1]];
            for (int d = 0; d < 4; d++)
