import java.util.*;

public class Main {
    // O(rows * cols) time, O(1) extra space
    static void setZeroes(int[][] m) {
        int rows = m.length, cols = m[0].length;
        boolean firstRowZero = false, firstColZero = false;
        for (int c = 0; c < cols; c++) if (m[0][c] == 0) firstRowZero = true;   // the notes' own state
        for (int r = 0; r < rows; r++) if (m[r][0] == 0) firstColZero = true;
        for (int r = 1; r < rows; r++)                  // pass 1: write the marks into row 0 and column 0
            for (int c = 1; c < cols; c++)
                if (m[r][c] == 0) { m[r][0] = 0; m[0][c] = 0; }
        for (int r = 1; r < rows; r++)                  // pass 2: clear inner cells from the marks
            for (int c = 1; c < cols; c++)
                if (m[r][0] == 0 || m[0][c] == 0) m[r][c] = 0;
        if (firstRowZero) for (int c = 0; c < cols; c++) m[0][c] = 0;           // last: the notes themselves
        if (firstColZero) for (int r = 0; r < rows; r++) m[r][0] = 0;
    }

    public static void main(String[] args) {
        int[][] m = {{0, 2, 3}, {4, 0, 6}, {7, 8, 9}, {1, 11, 12}};
        System.out.println("before: " + Arrays.deepToString(m));
        setZeroes(m);
        System.out.println("after:  " + Arrays.deepToString(m));
    }
}

