import java.util.*;

public class Main {
    // O(rows * cols) time. The queue lives on the heap, so a huge island cannot overflow the call stack
    static int numIslandsBfs(char[][] g) {
        int rows = g.length, cols = g[0].length, count = 0;
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++) {
                if (g[r][c] != '1') continue;
                count++;                                  // new island found
                Deque<int[]> queue = new ArrayDeque<>();
                g[r][c] = '0';                            // mark when pushed, not when popped
                queue.add(new int[] {r, c});
                while (!queue.isEmpty()) {
                    int[] cur = queue.poll();
                    for (int d = 0; d < 4; d++) {
                        int nr = cur[0] + dr[d], nc = cur[1] + dc[d];
                        if (nr >= 0 && nc >= 0 && nr < rows && nc < cols && g[nr][nc] == '1') {
                            g[nr][nc] = '0';
                            queue.add(new int[] {nr, nc});
                        }
                    }
                }
            }
        return count;
    }

    public static void main(String[] args) {
        String[] rows = {"11000", "11000", "00100", "00011"};
        char[][] g = new char[rows.length][];
        for (int i = 0; i < rows.length; i++) g[i] = rows[i].toCharArray();
        System.out.println("grid: " + String.join(" ", rows));
        System.out.println("islands: " + numIslandsBfs(g));

        int n = 2000;                                     // 4 million land cells, one big island
        char[][] big = new char[n][n];
        for (char[] row : big) Arrays.fill(row, '1');
        System.out.println("big " + n + "x" + n + " grid islands: " + numIslandsBfs(big));
    }
}

