                g[r][c] = '0';                            // mark when pushed, not when popped
                queue.Enqueue(new[] { r, c });
                while (queue.Count > 0)
                {
                    int[] cur = queue.Dequeue();
                    for (int d = 0; d < 4; d++)
                    {
                        int nr = cur[0] + dr[d], nc = cur[1] + dc[d];
                        if (nr >= 0 && nc >= 0 && nr < rows && nc < cols && g[nr][nc] == '1')
                        {
                            g[nr][nc] = '0';
                            queue.Enqueue(new[] { nr, nc });
                        }
                    }
                }
            }
        return count;
    }

    static void Main()
    {
        string[] rows = { "11000", "11000", "00100", "00011" };
        var g = new char[rows.Length][];
        for (int i = 0; i < rows.Length; i++) g[i] = rows[i].ToCharArray();
        Console.WriteLine("grid: " + string.Join(" ", rows));
        Console.WriteLine("islands: " + NumIslandsBfs(g));

        int n = 2000;                                     // 4 million land cells, one big island
        var big = new char[n][];
        for (int i = 0; i < n; i++) { big[i] = new char[n]; for (int j = 0; j < n; j++) big[i][j] = '1'; }
        Console.WriteLine("big " + n + "x" + n + " grid islands: " + NumIslandsBfs(big));
    }
}
